using System.Net.Http.Json;
using System.Text.Json.Serialization;
using ModelContextProtocol.Server;

namespace McpServer.Tools;

[McpServerToolType]
public sealed class WeatherTools
{
    [McpServerTool(Name = "get_weather"),
     Description("Get current weather for a location by latitude and longitude.")]
    public async Task<string> GetWeatherAsync(
        IHttpClientFactory httpClientFactory,
        [Description("Latitude of the location")] double latitude,
        [Description("Longitude of the location")] double longitude)
    {
        using var client = httpClientFactory.CreateClient("WeatherApi");

        var url = $"v1/forecast?latitude={latitude}&longitude={longitude}"
                + "&current=temperature_2m,wind_speed_10m";

        var response = await client.GetFromJsonAsync<WeatherResponse>(url);

        if (response?.Current is null)
            return "Unable to fetch weather data.";

        return $"Temperature: {response.Current.Temperature}°C, "
             + $"Wind: {response.Current.WindSpeed} km/h";
    }

    [McpServerTool(Name = "get_location_weather"),
     Description("Get weather for a named city using geocoding lookup.")]
    public async Task<string> GetLocationWeatherAsync(
        IHttpClientFactory httpClientFactory,
        [Description("City name to look up")] string city)
    {
        using var client = httpClientFactory.CreateClient("WeatherApi");

        var geoUrl = $"v1/search?name={Uri.EscapeDataString(city)}&count=1";
        var geo = await client.GetFromJsonAsync<GeoResponse>(geoUrl);

        if (geo?.Results is not { Count: > 0 })
            return $"Could not find location: {city}";

        var loc = geo.Results[0];
        return await GetWeatherAsync(httpClientFactory, loc.Latitude, loc.Longitude);
    }
}

// Response models
file record WeatherResponse(
    [property: JsonPropertyName("current")] CurrentWeather? Current);

file record CurrentWeather(
    [property: JsonPropertyName("temperature_2m")] double Temperature,
    [property: JsonPropertyName("wind_speed_10m")] double WindSpeed);

file record GeoResponse(
    [property: JsonPropertyName("results")] List<GeoResult>? Results);

file record GeoResult(
    [property: JsonPropertyName("latitude")] double Latitude,
    [property: JsonPropertyName("longitude")] double Longitude,
    [property: JsonPropertyName("name")] string Name);

